('anac', '67331b48-ac35-4dd8-a443-ec66b66a1894', 'Legislação Aeronáutica', null, 'A RESPONSABILIDADE PELA OBTENÇÃO E ATUALIZAÇÃO DO CERTIFICADO MÉDICO AERONÁUTICO (CMA) É DO(A)', null, '[{"letra": "A", "texto": "snea", "imagem_url": null}, {"letra": "B", "texto": "anac", "imagem_url": null}, {"letra": "C", "texto": "aeronauta", "imagem_url": null}, {"letra": "D", "texto": "operadora", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '676a8ed2-028a-4b07-8caa-87d0a47fb94a', 'Segurança e Emergência', null, 'A SEQÜÊNCIA CORRETA PARA UMA PESSOA ABANDONAR A AERONAVE ATRAVÉS DAS JANELAS DE EMERGÊNCIA DA CABINE DE COMANDO É PASSAR, INICIALMENTE:', null, '[{"letra": "A", "texto": "uma das pernas, a cabeça, a parte superior do tronco e por fim, a outra perna", "imagem_url": null}, {"letra": "B", "texto": "os braços, a parte superior do tronco e, finalmente as pernas", "imagem_url": null}, {"letra": "C", "texto": "a cabeça, a parte superior do tronco e por último as duas pernas", "imagem_url": null}, {"letra": "D", "texto": "as pernas e depois o restante do corpo", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '676bd7e6-b9fe-49b9-8513-4e7b2d81a34c', 'Segurança e Emergência', null, 'NO CHEQUE PRÉ-VOO DE UM INTERFONE, DEVE-SE VERIFICAR O (A)', null, '[{"letra": "A", "texto": "FIXAÇÃO, LACRES E FUNCIONAMENTO", "imagem_url": null}, {"letra": "B", "texto": "SINAL SONORO, O SINAL LUMINOSO E O FUNCIONAMENTO", "imagem_url": null}, {"letra": "C", "texto": "LIMPEZA DOS FONES, O FUNCIONAMENTO E O NÚMERO DO SERIAL", "imagem_url": null}, {"letra": "D", "texto": "SINAL VISUAL, O SINAL VIBRATÓRIO E O TECLADO ALFANUMÉRICO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '676e0d44-6eb0-4496-bf11-6699893375ec', 'Primeiros Socorros', null, 'DENTRE OS PRINCIPAIS RECURSOS DE PRIMEIROS-SOCORROS DENTRO DO AVIÃO, TEMOS OS KITS DE PRIMEIROS-SOCORROS, O SISTEMA PORTÁTIL DE OXIGÊNIO TERAPÊUTICO E OS (AS)', null, '[{"letra": "A", "texto": "MÓDULO GERADOR QUÍMICO DE OXIGÊNIO", "imagem_url": null}, {"letra": "B", "texto": "TIRAS DE ESCAPE RÁPIDO", "imagem_url": null}, {"letra": "C", "texto": "CONJUNTO MÉDICO DO KIT DE SOBREVIVÊNCIA", "imagem_url": null}, {"letra": "D", "texto": "EXTINTORES DE HALON", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '67b204e4-c23f-4662-96e2-fbb48e8b7515', 'Segurança e Emergência', null, 'PARA SE OBTER ÁGUA NA SELVA, NÃO SE ENCONTRANDO UM REGATO OU RIO, DEVE-SE:', null, '[{"letra": "A", "texto": "purificá-la com o dessalgante químico", "imagem_url": null}, {"letra": "B", "texto": "cavar o chão pelo menos 1/2 metro de profundidade", "imagem_url": null}, {"letra": "C", "texto": "retirá-la das folhas, não amargas, de alguns cipós", "imagem_url": null}, {"letra": "D", "texto": "purificá-la utilizando aralen", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '67b2baee-1a47-44de-9921-b4444d7c0707', 'Segurança e Emergência', null, 'APÓS O POUSO FORÇADO NA SELVA E CONSEQÜENTE EVACUAÇÃO DE EMERGÊNCIA, O MELHOR PROCEDIMENTO A SER ADOTADO PELOS SOBREVIVENTES SERÁ:', null, '[{"letra": "A", "texto": "permanecer perto da aeronave durante 24 horas, passado este prazo, deslocar os sobreviventes para perto de um rio", "imagem_url": null}, {"letra": "B", "texto": "usar a aeronave como abrigo para os feridos e metade do grupo, saindo a outra metade em busca de socorro", "imagem_url": null}, {"letra": "C", "texto": "se possível usar a aeronave como abrigo e esperar o salvamento", "imagem_url": null}, {"letra": "D", "texto": "procurar abrigo longe da aeronave e sair em busca de socorro", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '67b31c98-83c6-40fd-9ada-50f71f026334', 'Segurança e Emergência', null, 'PODE-SE DIZER QUE AGENTES EXTINTORES SÃO:', null, '[{"letra": "A", "texto": "aparelhos que operam com água", "imagem_url": null}, {"letra": "B", "texto": "toda substância ou material que pode ser utilizado para apagar um incêndio", "imagem_url": null}, {"letra": "C", "texto": "equipamentos de combate ao fogo", "imagem_url": null}, {"letra": "D", "texto": "elementos treinados que combatem o fogo", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '67baeea7-0556-426b-af14-9bc003b6fe9b', 'Segurança e Emergência', null, 'OS ALIMENTOS SILVESTRES ANTES DE SEREM INGERIDOS DEVEM SER COZIDOS PORQUE:', null, '[{"letra": "A", "texto": "ficam mais saborosos e oferecem menos perigo", "imagem_url": null}, {"letra": "B", "texto": "a maioria das pessoas têm o hábito de ingerir alimentos cozidos", "imagem_url": null}, {"letra": "C", "texto": "a baixa temperatura na selva requer alimentos quentes", "imagem_url": null}, {"letra": "D", "texto": "mantém certo valor nutritivo e oferecem menos perigo", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '67bdf5ff-815f-49c4-b7fb-ba304192677b', 'Primeiros Socorros', null, 'CABE ÀS COMPANHIAS AÉREAS E AOS TRIPULANTES REQUISITAREM UM ATESTADO/AUTORIZAÇÃO MÉDICA, PARA RESGUARDO DE RESPONSABILIDADE A BORDO, NOS CASOS DE PASSAGEIROS(AS) QUE ESTEJAM', null, '[{"letra": "A", "texto": "GRÁVIDAS", "imagem_url": null}, {"letra": "B", "texto": "ACIMA DO OITAVO MÊS DE GRAVIDEZ", "imagem_url": null}, {"letra": "C", "texto": "COM QUALQUER PARTE DO CORPO ENGESSADA", "imagem_url": null}, {"letra": "D", "texto": "COM FEBRE ALTA E DORES", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '67e44e14-036a-4773-9f6e-fdbfad8d4f14', 'Segurança e Emergência', null, 'PARA SE TORNAR MAIS FÁCIL A LOCALIZAÇÃO DOS SOBREVIVENTES, EM UM POUSO DE EMERGÊNCIA NA SELVA DEVE-SE:', null, '[{"letra": "A", "texto": "organizar grupos de observação", "imagem_url": null}, {"letra": "B", "texto": "determinar que se espalhem pela selva", "imagem_url": null}, {"letra": "C", "texto": "organizar uma caravana e sair em marcha marcando o caminho", "imagem_url": null}, {"letra": "D", "texto": "permanecer junto à aeronave e fazer todas sinalizações que forem possíveis", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '67e4da79-1af7-4a8c-b5e4-2afb859b2d91', 'Legislação Aeronáutica', null, 'UMA TRIPULAÇÃO SIMPLES PODERÁ SE TRANSFORMAR EM COMPOSTA:', null, '[{"letra": "A", "texto": "somente na origem do voo", "imagem_url": null}, {"letra": "B", "texto": "somente na base da tripulação", "imagem_url": null}, {"letra": "C", "texto": "se o comandante mandar", "imagem_url": null}, {"letra": "D", "texto": "quando houver ampliação da jornada", "imagem_url": null}]'::jsonb, 'A', null),
