('anac', '68e9bfd0-61e8-40e1-9b25-b1fa2f7c0ce1', 'Segurança e Emergência', null, 'O SISTEMA DE OXIGÊNIO FIXO EXISTENTE NA AERONAVE É DIVIDIDO EM:', null, '[{"letra": "A", "texto": "dois, sendo um para a cabine de comando e um para galley traseira", "imagem_url": null}, {"letra": "B", "texto": "dois, sendo um para a cabine de comando e um para cabine de passageiros", "imagem_url": null}, {"letra": "C", "texto": "uma para cada tripulante", "imagem_url": null}, {"letra": "D", "texto": "um para cada tripulante da cabine de comando", "imagem_url": null}]'::jsonb, 'B', null),
