('anac', '691adbad-12b8-4a96-be12-1977e492817d', 'Conhecimentos Técnicos', null, 'A SUPERFÍCIE DE COMANDO DO AVIÃO QUE COMANDA OS MOVIMENTOS DE ROLAGEM É O:', null, '[{"letra": "A", "texto": "leme de direção", "imagem_url": null}, {"letra": "B", "texto": "profundor", "imagem_url": null}, {"letra": "C", "texto": "aileron", "imagem_url": null}, {"letra": "D", "texto": "flap", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '693c7ed9-24b6-41a4-86a3-b1cdbb73d231', 'Segurança e Emergência', null, 'EM UMA SITUAÇÃO DE EMERGÊNCIA REAL, A INSTRUÇÃO QUE DEVERÁ SER DADA AOS PASSAGEIROS, EM RELAÇÃO À UTILIZAÇÃO DOS COLETES SALVA-VIDAS, ORIENTA PARA QUE ESTES SEJAM INFLADOS:', null, '[{"letra": "A", "texto": "quando os passageiros estiverem de pé no corredor", "imagem_url": null}, {"letra": "B", "texto": "após o pouso, dentro da aeronave", "imagem_url": null}, {"letra": "C", "texto": "com os passageiros sentados em seus lugares, antes do pouso", "imagem_url": null}, {"letra": "D", "texto": "na soleira da porta ou sobre a asa, antes de abandonar a aeronave", "imagem_url": null}]'::jsonb, 'D', null),
