('anac', '8111ffb6-0173-4a6a-9c9b-d73bb31d994d', 'Legislação Aeronáutica', null, 'O AERONAUTA EMPREGADO EM EMPRESA AÉREA REGULAR (RBAC121), SE INTEGRANTE DE UMA TRIPULAÇÃO COMPOSTA, TEM COMO LIMITE DE VOO E DE POUSO:', null, '[{"letra": "A", "texto": "9 HORAS E 3 POUSOS", "imagem_url": null}, {"letra": "B", "texto": "11 HORAS E 5 POUSOS", "imagem_url": null}, {"letra": "C", "texto": "12 HORAS E 6 POUSOS", "imagem_url": null}, {"letra": "D", "texto": "10 HORAS E 4 POUSOS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '811fcb96-c417-408e-96e9-4f579c2ef599', 'Primeiros Socorros', null, 'EM PASSAGEIROS QUE APRESENTEM DIARRÉIA ABUNDANTE, PODERÁ OCORRER UMA GRAVE COMPLICAÇÃO.IDENTIFIQUE-A ABAIXO:', null, '[{"letra": "A", "texto": "vômitos", "imagem_url": null}, {"letra": "B", "texto": "convulsão", "imagem_url": null}, {"letra": "C", "texto": "febre", "imagem_url": null}, {"letra": "D", "texto": "desidratação", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '81236cdc-c2f3-4808-b6e8-4b5c4468a742', 'Conhecimentos Técnicos', null, 'QUANTO AO TREM DE POUSO, QUANDO A BEQUILHA ESTÁ LOCALIZADA NA CAUDA DIZEMOS QUE O AVIÃO É:', null, '[{"letra": "A", "texto": "convencional", "imagem_url": null}, {"letra": "B", "texto": "anfíbio", "imagem_url": null}, {"letra": "C", "texto": "retrátil", "imagem_url": null}, {"letra": "D", "texto": "triciclo", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '8127cbcb-4635-41a0-b7d0-5ab9dd5dce48', 'Segurança e Emergência', null, 'DURANTE UMA TURBULÊNCIA OS COMISSÁRIOS DEVEM:', null, '[{"letra": "A", "texto": "circular pelo corredor para ver se está tudo bem", "imagem_url": null}, {"letra": "B", "texto": "ficar em seus assentos sem colocar o cinto de segurança", "imagem_url": null}, {"letra": "C", "texto": "efetuar o serviço de bordo normalmente", "imagem_url": null}, {"letra": "D", "texto": "ficar e seus assentos com os cintos afivelados", "imagem_url": null}]'::jsonb, 'D', null),
