('anac', '81555ddf-e2f0-4fc2-bc6c-9010e22ceeab', 'Primeiros Socorros', null, 'NO AFOGADO PÁLIDO DEVE-SE:', null, '[{"letra": "A", "texto": "iniciar a respiração artificial e, caso necessário, aplicar RCP com oxigênio", "imagem_url": null}, {"letra": "B", "texto": "iniciar dando golpes pré cocliais", "imagem_url": null}, {"letra": "C", "texto": "retirar água dos pulmões", "imagem_url": null}, {"letra": "D", "texto": "retirar água dos pulmões e oxigênio", "imagem_url": null}]'::jsonb, 'A', null),
